"use strict";(globalThis.webpackChunkprotoflow_docs=globalThis.webpackChunkprotoflow_docs||[]).push([[133],{6367:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>d,contentTitle:()=>s,default:()=>u,frontMatter:()=>r,metadata:()=>t,toc:()=>l});const t=JSON.parse('{"id":"introduction/index","title":"Introduction","description":"Flows shape the performance of many engineered systems. They determine how much lift an aircraft produces and how efficiently a car moves through the air, but they are equally important in a wide range of mechanical engineering applications, including heat exchangers, ventilation systems, turbomachinery, energy systems, and electronic cooling. In many cases, the behavior of a fluid directly determines a system\'s efficiency, reliability, and operating limits.","source":"@site/docs/01-introduction/index.md","sourceDirName":"01-introduction","slug":"/","permalink":"/Wind-tunnel-book/","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"index","title":"Introduction","sidebar_label":"Introduction","slug":"/"},"sidebar":"courseSidebar","next":{"title":"Wind Tunnel Fundamentals","permalink":"/Wind-tunnel-book/fundamentals"}}');var o=i(4848),a=i(8453);const r={id:"index",title:"Introduction",sidebar_label:"Introduction",slug:"/"},s="Introduction",d={},l=[];function c(e){const n={a:"a",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"introduction",children:"Introduction"})}),"\n",(0,o.jsx)(n.p,{children:"Flows shape the performance of many engineered systems. They determine how much lift an aircraft produces and how efficiently a car moves through the air, but they are equally important in a wide range of mechanical engineering applications, including heat exchangers, ventilation systems, turbomachinery, energy systems, and electronic cooling. In many cases, the behavior of a fluid directly determines a system's efficiency, reliability, and operating limits."}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.a,{href:"https://en.wikipedia.org/wiki/Wind_tunnel",children:"Wind tunnels"})," have helped engineers study airflow for more than a century. The first enclosed wind tunnel, built by Francis Herbert Wenham in 1871, offered a more controlled way to study aerodynamic forces than experiments with moving objects in open air. Since then, wind tunnels have evolved from relatively simple experimental facilities into highly sophisticated research and industrial tools capable of reproducing a wide range of flow conditions, measuring forces with great precision, and visualizing complex flow phenomena. Despite enormous advances in computational modeling, wind tunnels remain essential today both for investigating flow behavior and for validating the models used to predict it [",(0,o.jsx)(n.a,{href:"/references#barlow1999",children:"Barlow et al., 1999"}),"]."]}),"\n",(0,o.jsx)(n.p,{children:"Engineering design involving fluid flows relies on a combination of modeling, experimentation, and real-world testing. Mathematical and computational models provide rapid insight into design trends and underlying physics, but inevitably rely on simplifying assumptions. Wind-tunnel experiments offer controlled measurements and flow visualization, yet are often performed on scaled models under idealized conditions. Real-world testing captures the true operating environment, but is typically more expensive, less controlled, and more difficult to interpret. Aerodynamic design therefore hinges on the integrated consideration of all three approaches. The learning process driven by the continuous increase of understanding of the discrepancies and similarities between approaches is not only essential to achieve successful aerodynamic designs, but also to train aerodynamic intuition."}),"\n",(0,o.jsx)(n.p,{children:"The ProtoFlow educational wind tunnel is designed to accelerate this learning process by making experimentation fast, iterative, and accessible. Students can design a geometry, 3D-print a test object, and measure its aerodynamic forces and the surrounding flow within a short period of time. Rather than treating a wind-tunnel experiment as a weeks-long project, ProtoFlow encourages rapid cycles of prediction, testing, observation, and redesign. By repeatedly comparing expectations with measurements and immediately testing new ideas, students gradually develop intuition for the relationships between theoretical models, experiments, and real flows."})]})}function u(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},8453:(e,n,i)=>{i.d(n,{R:()=>r,x:()=>s});var t=i(6540);const o={},a=t.createContext(o);function r(e){const n=t.useContext(a);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),t.createElement(a.Provider,{value:n},e.children)}}}]);